// B"H
class LruCache{constructor(limitBytes){this.limitBytes=limitBytes;this.bytes=0;this.map=new Map();}get(k){const v=this.map.get(k);if(!v)return null;this.map.delete(k);this.map.set(k,v);return v.value;}set(k,value,bytes){if(this.map.has(k)){this.bytes-=this.map.get(k).bytes;this.map.delete(k);}this.map.set(k,{value,bytes});this.bytes+=bytes;while(this.bytes>this.limitBytes&&this.map.size){const first=this.map.keys().next().value;this.bytes-=this.map.get(first).bytes;this.map.delete(first);}}summary(){return{items:this.map.size,bytes:this.bytes,limitBytes:this.limitBytes};}}module.exports={LruCache};
